# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">THEME 4: FUTURE CONTINUOUS vs. FUTURE PERFECT TENSE (E12.4)</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">Future Continuous Tense</text>\n  <text x="180" y="86" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1d4ed8">Subject + will be + V-ing</text>\n  <rect x="34" y="98" width="292" height="58" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="44" y="116" font-size="10.5" font-weight="bold" fill="#1e3a8a">Kullanım (Action in progress at a future time):</text>\n  <text x="44" y="132" font-size="10" fill="#1e3a8a">Gelecekte belirli bir anda devam ediyor olacak</text>\n  <text x="44" y="146" font-size="10" fill="#1e3a8a">eylemleri ifade eder.</text>\n  <text x="34" y="174" font-size="10.5" font-weight="bold" fill="#1d4ed8">Zaman İfadeleri (Time Expressions):</text>\n  <text x="34" y="190" font-size="10" fill="#1e3a8a">• this time tomorrow / this time next week</text>\n  <text x="34" y="205" font-size="10" fill="#1e3a8a">• at 10 o\'clock tomorrow / in ten years\' time</text>\n  <text x="34" y="224" font-size="10" font-style="italic" fill="#1e40af">"This time next year, we will be using flying cars."</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">Future Perfect Tense</text>\n  <text x="520" y="86" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#15803d">Subject + will have + V₃ (Past Participle)</text>\n  <rect x="374" y="98" width="292" height="58" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="384" y="116" font-size="10.5" font-weight="bold" fill="#14532d">Kullanım (Completed action before a future point):</text>\n  <text x="384" y="132" font-size="10" fill="#14532d">Gelecekte belirli bir tarihten önce tamamlanmış</text>\n  <text x="384" y="146" font-size="10" fill="#14532d">(bitmiş) olacak eylemleri anlatır.</text>\n  <text x="374" y="174" font-size="10.5" font-weight="bold" fill="#15803d">Zaman İfadeleri (Time Expressions):</text>\n  <text x="374" y="190" font-size="10" fill="#14532d">• by 2030 / by the end of this century</text>\n  <text x="374" y="205" font-size="10" fill="#14532d">• by the time + Simple Present / before / within</text>\n  <text x="374" y="224" font-size="10" font-style="italic" fill="#166534">"By 2050, scientists will have colonized Mars."</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">CYBER SECURITY, DIGITAL THREATS AND ONLINE SAFETY</text>\n  <rect x="20" y="46" width="320" height="194" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#991b1b">Cyber Threats &amp; Crimes (Siber Tehditler)</text>\n  <text x="34" y="92" font-size="10.5" fill="#7f1d1d">• <tspan font-weight="bold">Phishing (Oltalama):</tspan> Fake emails/links to</text>\n  <text x="44" y="107" font-size="10" fill="#7f1d1d">steal passwords and credit card details.</text>\n  <text x="34" y="127" font-size="10.5" fill="#7f1d1d">• <tspan font-weight="bold">Malware &amp; Ransomware:</tspan> Malicious software</text>\n  <text x="44" y="142" font-size="10" fill="#7f1d1d">that locks or damages computer systems.</text>\n  <text x="34" y="162" font-size="10.5" fill="#7f1d1d">• <tspan font-weight="bold">Identity Theft (Kimlik Hırsızlığı):</tspan> Using</text>\n  <text x="44" y="177" font-size="10" fill="#7f1d1d">someone\'s personal data illegally for fraud.</text>\n  <text x="34" y="197" font-size="10.5" fill="#7f1d1d">• <tspan font-weight="bold">Data Breach (Veri İhlali):</tspan> Unauthorized</text>\n  <text x="44" y="212" font-size="10" fill="#7f1d1d">access to confidential user information.</text>\n  <rect x="360" y="46" width="320" height="194" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">Cyber Security Precautions (Önlemler)</text>\n  <rect x="374" y="82" width="292" height="34" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="520" y="103" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">1. Strong Passwords &amp; Two-Factor Authentication (2FA)</text>\n  <rect x="374" y="122" width="292" height="34" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="520" y="143" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">2. Firewall, Antivirus &amp; Regular Software Updates</text>\n  <rect x="374" y="162" width="292" height="34" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="520" y="183" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">3. Data Encryption &amp; Cloud Backup (Veri Şifreleme)</text>\n  <rect x="374" y="202" width="292" height="28" rx="6" fill="#dbeafe" stroke="#2563eb"/>\n  <text x="520" y="220" text-anchor="middle" font-size="10" font-weight="bold" fill="#1e40af">Do not click suspicious links or share personal data!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">FUTURE TECHNOLOGY, ROBOTICS AND BIO-ENGINEERING VOCABULARY</text>\n  <rect x="20" y="48" width="210" height="190" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="125" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">Robotics &amp; Automation</text>\n  <text x="32" y="95" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">Autonomous vehicles:</tspan></text>\n  <text x="40" y="110" font-size="10" fill="#78350f">Driverless / self-driving cars</text>\n  <text x="32" y="132" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">Humanoid robots:</tspan></text>\n  <text x="40" y="147" font-size="10" fill="#78350f">Robots resembling human body</text>\n  <text x="32" y="169" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">Nanotechnology:</tspan></text>\n  <text x="40" y="184" font-size="10" fill="#78350f">Micro-scale medical robots</text>\n  <text x="32" y="206" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">Smart homes (IoT):</tspan></text>\n  <text x="40" y="221" font-size="10" fill="#78350f">Connected devices &amp; sensors</text>\n  <rect x="245" y="48" width="210" height="190" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="350" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">Virtual &amp; Space Tech</text>\n  <text x="257" y="95" font-size="10.5" fill="#581c87">• <tspan font-weight="bold">Virtual Reality (VR):</tspan></text>\n  <text x="265" y="110" font-size="10" fill="#581c87">3D simulated digital world</text>\n  <text x="257" y="132" font-size="10.5" fill="#581c87">• <tspan font-weight="bold">Augmented Reality (AR):</tspan></text>\n  <text x="265" y="147" font-size="10" fill="#581c87">Digital overlay on real world</text>\n  <text x="257" y="169" font-size="10.5" fill="#581c87">• <tspan font-weight="bold">Holographic calls:</tspan></text>\n  <text x="265" y="184" font-size="10" fill="#581c87">3D projection communication</text>\n  <text x="257" y="206" font-size="10.5" fill="#581c87">• <tspan font-weight="bold">Space tourism:</tspan></text>\n  <text x="265" y="221" font-size="10" fill="#581c87">Orbital travel for civilians</text>\n  <rect x="470" y="48" width="210" height="190" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="575" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">Key Verbs &amp; Adjectives</text>\n  <text x="482" y="95" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">predict / foresee:</tspan> öngörmek</text>\n  <text x="482" y="115" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">transform:</tspan> dönüştürmek</text>\n  <text x="482" y="135" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">implant:</tspan> çip/doku yerleştirmek</text>\n  <text x="482" y="155" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">cutting-edge:</tspan> son teknoloji</text>\n  <text x="482" y="175" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">inevitable:</tspan> kaçınılmaz</text>\n  <text x="482" y="195" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">obsolete:</tspan> modası geçmiş / eski</text>\n  <text x="482" y="215" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">sustainable:</tspan> sürdürülebilir</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
